    #[tokio::test]
    async fn verify_reports_audit_event_id_duplicate_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let shared = Uuid::new_v4();
        // Two audit rows sharing one non-nil id: a replayed or duplicated
        // audit-log row no production write emits, since every record() call
        // allocates a fresh Uuid::new_v4().
        for _ in 0..2 {
            s.audit
                .record(AuditEvent {
                    id: shared,
                    timestamp_ms: epoch_ms(),
                    issuer: me.clone(),
                    kind: AuditKind::AuthenticationFailed {
                        transport: "ipc".into(),
                        reason: "fixture".into(),
                    },
                })
                .await
                .unwrap();
        }
        // A nil-id pair must NOT surface as audit_event_id_duplicate: the nil
        // UUID is owned per-row by audit_event_id_nil, and the cardinality pass
        // skips it so serde-defaulted rows are not conflated with a real id
        // collision.
        for _ in 0..2 {
            s.audit
                .record(AuditEvent {
                    id: Uuid::nil(),
                    timestamp_ms: epoch_ms(),
                    issuer: me.clone(),
                    kind: AuditKind::AuthenticationFailed {
                        transport: "ipc".into(),
                        reason: "fixture".into(),
                    },
                })
                .await
                .unwrap();
        }

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let dups: Vec<_> = drift
                    .iter()
                    .filter(|item| item.kind == "audit_event_id_duplicate")
                    .collect();
                assert_eq!(
                    dups.len(),
                    1,
                    "exactly one audit_event_id_duplicate row, and the nil pair must be skipped: {drift:?}"
                );
                let row = dups[0];
                let shared_str = shared.to_string();
                assert_eq!(row.id.as_deref(), Some(shared_str.as_str()));
                assert!(
                    row.message.contains("2 audit events share id")
                        && row.message.contains("Uuid::new_v4()"),
                    "drift message should count the shared rows and name the new_v4 invariant: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("Uuid::new_v4()"),
                    "repair hint should name Uuid::new_v4: {}",
                    row.repair
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity.message.contains("1 duplicate-id audit event"),
                    "check message should count duplicate-id events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_external_payment_settled_receipt_id_shared_by_multiple_events_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        // Two ExternalPaymentSettled rows with DISTINCT event ids sharing one
        // non-nil receipt_id: the replayed or duplicated paid-call audit row no
        // production write emits, since record_paid_call mints a fresh
        // receipt_id = Uuid::new_v4() per call and records exactly one
        // ExternalPaymentSettled carrying it. The distinct event ids keep this
        // off the event.id-keyed audit_event_id_duplicate arm.
        let shared = Uuid::new_v4();
        for _ in 0..2 {
            s.audit
                .record(AuditEvent {
                    id: Uuid::new_v4(),
                    timestamp_ms: epoch_ms(),
                    issuer: me.clone(),
                    kind: AuditKind::ExternalPaymentSettled {
                        provider: "hyre".into(),
                        endpoint: "https://api.hyre.example/v1/data".into(),
                        network: "base-sepolia".into(),
                        asset: "USDC".into(),
                        amount: "10000".into(),
                        receipt_id: shared,
                    },
                })
                .await
                .unwrap();
        }
        // A nil-receipt_id pair must NOT surface as the cardinality drift: the
        // nil UUID is owned per row by audit_external_payment_settled_receipt_id_nil,
        // and the cardinality pass skips it so serde-defaulted rows are not
        // conflated with a real receipt_id collision. Distinct event ids keep it
        // off audit_event_id_duplicate too.
        for _ in 0..2 {
            s.audit
                .record(AuditEvent {
                    id: Uuid::new_v4(),
                    timestamp_ms: epoch_ms(),
                    issuer: me.clone(),
                    kind: AuditKind::ExternalPaymentSettled {
                        provider: "hyre".into(),
                        endpoint: "https://api.hyre.example/v1/data".into(),
                        network: "base-sepolia".into(),
                        asset: "USDC".into(),
                        amount: "10000".into(),
                        receipt_id: Uuid::nil(),
                    },
                })
                .await
                .unwrap();
        }

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let dups: Vec<_> = drift
                    .iter()
                    .filter(|item| {
                        item.kind == "external_payment_settled_receipt_id_shared_by_multiple_events"
                    })
                    .collect();
                assert_eq!(
                    dups.len(),
                    1,
                    "exactly one external_payment_settled_receipt_id_shared_by_multiple_events row, and the nil pair must be skipped: {drift:?}"
                );
                let row = dups[0];
                assert_eq!(row.id.as_deref(), Some(shared.to_string().as_str()));
                assert!(
                    row.message
                        .contains("ExternalPaymentSettled audit events share receipt_id")
                        && row.message.contains("Uuid::new_v4()"),
                    "drift message should count the shared rows and name the new_v4 invariant: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("receipt_id_duplicate")
                        && row
                            .repair
                            .contains("budget_debit_paired_receipt_shared_by_multiple_debits"),
                    "repair hint should name the sibling cardinality legs: {}",
                    row.repair
                );
                // Distinct event ids: the event.id-keyed arm must stay silent.
                assert!(
                    !drift
                        .iter()
                        .any(|item| item.kind == "audit_event_id_duplicate"),
                    "distinct event ids must not trip audit_event_id_duplicate: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 duplicate-receipt-id ExternalPaymentSettled audit event"),
                    "check message should count duplicate-receipt-id ExternalPaymentSettled events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

