    #[tokio::test]
    async fn verify_reports_audit_capability_granted_signature_b58_decodes_to_wrong_byte_length_drift(
    ) {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let event_id = Uuid::new_v4();
        // 87 chars (inside the 87..=88 wrong-length bound) and valid base58, but
        // decodes to 63 bytes — not the 64 of an ed25519 signature — so only the
        // decoded-byte-length arm fires.
        let sig = bs58::encode([0xFFu8; 63]).into_string();
        assert!(
            (87..=88).contains(&sig.chars().count()),
            "fixture signature must sit inside the 87..=88 length bound"
        );
        let decoded = bs58::decode(sig.as_bytes()).into_vec().unwrap();
        assert_ne!(
            decoded.len(),
            64,
            "fixture signature must decode to a non-64 byte length"
        );
        s.audit
            .record(AuditEvent {
                id: event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::CapabilityGranted {
                    subject_display: me.display.clone(),
                    action: "memory.read".into(),
                    granted_by_display: me.display.clone(),
                    signature_b58: sig,
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind
                            == "audit_capability_granted_signature_b58_decodes_to_wrong_byte_length"
                            && item.id.as_deref() == Some(&event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!("expected audit_capability_granted_signature_b58_decodes_to_wrong_byte_length: {drift:?}")
                    });
                assert!(
                    row.message.contains("AuditKind::CapabilityGranted")
                        && row.message.contains("not the 64 bytes"),
                    "drift message should name the CapabilityGranted variant and the 64-byte invariant: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("decodes to exactly 64 bytes")
                        && row.repair.contains("87..=88"),
                    "repair hint should name the 64-byte invariant and the length/charset bypass: {}",
                    row.repair
                );
                assert!(
                    drift.iter().all(|item| {
                        item.kind != "audit_capability_granted_signature_b58_empty"
                            && item.kind != "audit_capability_granted_signature_b58_wrong_length"
                            && item.kind != "audit_capability_granted_signature_b58_not_base58"
                    }),
                    "decoded-byte-length arm must not double-count as the empty, wrong-length, or charset arm: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity.message.contains(
                        "1 wrong-byte-length-signature-b58 CapabilityGranted audit event"
                    ),
                    "check message should count wrong-byte-length-signature-b58 CapabilityGranted events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

