    #[tokio::test]
    async fn verify_reports_audit_budget_requested_not_intent_dispatch_drift() {
        // BudgetExhausted and BudgetUnseeded both stamp `requested` from the one
        // `let requested = intent_dispatch_credits()` binding in dispatch_intent_run
        // (a daemon constant = 1), so a faithful row always carries
        // requested == intent_dispatch_credits(). A non-zero requested that is not
        // the flat cost is drift the requested_zero arm (zero only) and the
        // tokens_remaining_ge_requested arm (a two-field relation) both miss — these
        // are the audit-log carriers of the flat-dispatch-cost invariant. Controls
        // at requested = 1 must stay silent.
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let exhausted_id = Uuid::new_v4();
        let unseeded_id = Uuid::new_v4();
        let exhausted_control = Uuid::new_v4();
        let unseeded_control = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: exhausted_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::BudgetExhausted {
                    agent_display: "research@agent".into(),
                    intent_id: Uuid::new_v4(),
                    intent_text: "drift intent".into(),
                    requested: 2,
                    tokens_remaining: 0,
                    refill_eta_ms: 1_000,
                },
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: unseeded_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::BudgetUnseeded {
                    agent_display: "research@agent".into(),
                    intent_id: Uuid::new_v4(),
                    requested: 3,
                },
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: exhausted_control,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::BudgetExhausted {
                    agent_display: "research@agent".into(),
                    intent_id: Uuid::new_v4(),
                    intent_text: "ok intent".into(),
                    requested: 1,
                    tokens_remaining: 0,
                    refill_eta_ms: 1_000,
                },
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: unseeded_control,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::BudgetUnseeded {
                    agent_display: "research@agent".into(),
                    intent_id: Uuid::new_v4(),
                    requested: 1,
                },
            })
            .await
            .unwrap();

        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let fired = |kind: &str, id: Uuid| {
                    drift.iter().any(|item| {
                        item.kind == kind && item.id.as_deref() == Some(id.to_string().as_str())
                    })
                };
                assert!(
                    fired(
                        "audit_budget_exhausted_requested_not_intent_dispatch",
                        exhausted_id
                    ),
                    "exhausted arm must fire for requested=2: {drift:?}"
                );
                assert!(
                    fired(
                        "audit_budget_unseeded_requested_not_intent_dispatch",
                        unseeded_id
                    ),
                    "unseeded arm must fire for requested=3: {drift:?}"
                );
                // Controls at the flat cost stay silent.
                assert!(
                    !fired(
                        "audit_budget_exhausted_requested_not_intent_dispatch",
                        exhausted_control
                    ),
                    "exhausted arm must not fire for requested=1: {drift:?}"
                );
                assert!(
                    !fired(
                        "audit_budget_unseeded_requested_not_intent_dispatch",
                        unseeded_control
                    ),
                    "unseeded arm must not fire for requested=1: {drift:?}"
                );
                // Disjoint from the zero-sentinel arm (requested != 0) and the
                // two-field relation arm (tokens_remaining 0 >= requested 2 is false).
                assert!(
                    !fired("audit_budget_exhausted_requested_zero", exhausted_id)
                        && !fired("audit_budget_unseeded_requested_zero", unseeded_id),
                    "requested_zero arms must not fire for non-zero requested: {drift:?}"
                );
                assert!(
                    !fired(
                        "audit_budget_exhausted_tokens_remaining_ge_requested",
                        exhausted_id
                    ),
                    "tokens_remaining_ge_requested must not fire (0 >= 2 is false): {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 not-intent-dispatch-requested BudgetExhausted")
                        && integrity
                            .message
                            .contains("1 not-intent-dispatch-requested BudgetUnseeded"),
                    "check should count both not-intent-dispatch-requested carriers: {}",
                    integrity.message
                );
                assert!(orphans_total >= 2);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

