    #[tokio::test]
    async fn verify_reports_audit_external_payment_settled_amount_not_decimal_u128_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let event_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::ExternalPaymentSettled {
                    provider: "hyre".into(),
                    endpoint: "https://api.hyre.example/v1/data".into(),
                    network: "base-sepolia".into(),
                    asset: "USDC".into(),
                    // Human-readable units instead of atomic; fails parse::<u128>().
                    // receipt_id is valid so only the amount arm fires.
                    amount: "0.08".into(),
                    receipt_id: Uuid::new_v4(),
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "audit_external_payment_settled_amount_not_decimal_u128"
                            && item.id.as_deref() == Some(&event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "expected audit_external_payment_settled_amount_not_decimal_u128: {drift:?}"
                        )
                    });
                assert!(
                    row.message.contains("AuditKind::ExternalPaymentSettled"),
                    "drift message should name the ExternalPaymentSettled variant: {}",
                    row.message
                );
                assert!(
                    row.message.contains("does not parse as a decimal u128"),
                    "drift message should name the non-decimal-u128-amount invariant: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("parse::<u128>") && row.repair.contains("atomic"),
                    "repair hint should name parse::<u128> and atomic units: {}",
                    row.repair
                );
                assert!(
                    !drift
                        .iter()
                        .any(|item| item.kind == "audit_external_payment_settled_receipt_id_nil"),
                    "valid receipt_id must not trip the receipt_id_nil arm: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 not-decimal-u128-amount ExternalPaymentSettled audit event"),
                    "check message should count not-decimal-u128-amount ExternalPaymentSettled events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_external_payment_settled_receipt_resource_not_tool_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        // record_paid_call writes the SettlementReceipt with resource =
        // ResourceKind::Tool and the ExternalPaymentSettled audit with the same
        // receipt_id in one call. Here the joined receipt carries a non-Tool
        // resource (Compute) — the relabel a JSONL edit would make to
        // miscategorize an external paid call — while the audit row keeps a valid
        // non-nil receipt_id and a decimal amount, so only the cross-record
        // resource arm fires.
        let receipt_id = Uuid::new_v4();
        s.settlement
            .record(SettlementReceipt {
                id: receipt_id,
                payer: me.clone(),
                resource: ResourceKind::Compute,
                memory_record_id: None,
                credits_consumed: 5,
                settled_at: epoch_ms(),
                chain: None,
                cluster: None,
                batch_id: None,
                merkle_root: None,
                tx_sig: None,
                slot: None,
                confirmed_at: None,
                onchain_sig: None,
            })
            .await
            .unwrap();
        let event_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::ExternalPaymentSettled {
                    provider: "hyre".into(),
                    endpoint: "https://api.hyre.example/v1/data".into(),
                    network: "base-sepolia".into(),
                    asset: "USDC".into(),
                    amount: "10000".into(),
                    receipt_id,
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "external_payment_settled_receipt_resource_not_tool"
                            && item.id.as_deref() == Some(&event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "expected external_payment_settled_receipt_resource_not_tool: {drift:?}"
                        )
                    });
                assert!(
                    row.message.contains("AuditKind::ExternalPaymentSettled"),
                    "drift message should name the ExternalPaymentSettled variant: {}",
                    row.message
                );
                assert!(
                    row.message.contains("rather than ResourceKind::Tool"),
                    "drift message should name the Tool-resource invariant: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("record_paid_call")
                        && row.repair.contains("ResourceKind::Tool"),
                    "repair hint should name record_paid_call and ResourceKind::Tool: {}",
                    row.repair
                );
                assert!(
                    !drift
                        .iter()
                        .any(|item| item.kind == "audit_external_payment_settled_receipt_id_nil"),
                    "valid receipt_id must not trip the receipt_id_nil arm: {drift:?}"
                );
                assert!(
                    !drift.iter().any(|item| {
                        item.kind == "audit_external_payment_settled_amount_not_decimal_u128"
                    }),
                    "decimal amount must not trip the amount arm: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 resource-not-tool ExternalPaymentSettled receipt"),
                    "check message should count resource-not-tool ExternalPaymentSettled receipts: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

