    #[tokio::test]
    async fn verify_reports_budget_debit_paired_receipt_resource_not_tool_or_memory_drift() {
        let s = server_with(vec![], "");
        // The only two production (BudgetDebit, SettlementReceipt) pairings are
        // record_paid_call's Tool receipt and dispatch_intent_run's Memory
        // receipt. A debit paired to a receipt of any third resource kind (here
        // ResourceKind::Message) is a pairing no production write emits: it
        // falls through both the Memory branch and the Tool gate and must trip
        // the resource-not-tool-or-memory arm. memory_record_id is None and the
        // receipt joins no ExternalPaymentSettled audit, so the receipt-side
        // memory_receipt_resource_mismatch and audit resource arms stay silent
        // and this budget-join arm is the sole detector.
        let receipt_id = Uuid::new_v4();
        let payer = AgentId::new("payer@host", [9u8; 32]);
        s.settlement
            .record(budget_join_test_receipt(
                receipt_id,
                payer.clone(),
                ResourceKind::Message,
                5,
            ))
            .await
            .unwrap();
        s.budget.set_capacity(&payer, 100).await.unwrap();
        s.budget.try_debit(&payer, 5, receipt_id).await.unwrap();

        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "budget_debit_paired_receipt_resource_not_tool_or_memory"
                            && item.id.as_deref() == Some(&receipt_id.to_string())
                    })
                    .unwrap_or_else(|| panic!("expected resource drift: {drift:?}"));
                assert!(
                    row.message.contains("Message"),
                    "message should name the receipt resource: {}",
                    row.message
                );
                assert!(
                    !drift.iter().any(|i| {
                        i.kind == "budget_debit_paired_receipt_payer_mismatch"
                            || i.kind == "budget_debit_paired_receipt_payer_display_mismatch"
                            || i.kind == "budget_debit_paired_receipt_credits_mismatch"
                            || i.kind
                                == "budget_debit_paired_memory_receipt_credits_not_intent_dispatch"
                    }),
                    "a non-Tool/non-Memory paired receipt must trip only the resource arm: {drift:?}"
                );
                let check = checks
                    .iter()
                    .find(|c| c.name == "budget ↔ receipts")
                    .unwrap_or_else(|| panic!("expected budget join check: {checks:?}"));
                assert!(!check.passed);
                assert!(
                    check.message.contains("1 non-tool-or-memory-resource"),
                    "check message should count the resource mismatch: {}",
                    check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_budget_debit_agent_pubkey_zeroed_drift() {
        let s = server_with(vec![], "");
        // A zeroed debit agent (an anonymized "charged nobody" budget row) is
        // caught by the budget_debit_agent_pubkey_zeroed within-row shape arm,
        // the sixth carrier of the zeroed-pubkey family, which owns the all-zero
        // sentinel for the debit side. The budget_debit_paired_receipt_payer_mismatch
        // join arm gates on debit.agent.pubkey != [0u8; 32], so even with a
        // valid Tool receipt to join against (credits agree) the payer-mismatch
        // arm stays silent and only the shape arm fires.
        let receipt_id = Uuid::new_v4();
        let payer = AgentId::new("payer@host", [7u8; 32]);
        s.settlement
            .record(budget_join_test_receipt(
                receipt_id,
                payer,
                ResourceKind::Tool,
                4,
            ))
            .await
            .unwrap();
        let zeroed = AgentId::new("anon", [0u8; 32]);
        s.budget.set_capacity(&zeroed, 100).await.unwrap();
        s.budget.try_debit(&zeroed, 4, receipt_id).await.unwrap();

        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let matches: Vec<_> = drift
                    .iter()
                    .filter(|i| i.kind == "budget_debit_agent_pubkey_zeroed")
                    .collect();
                assert_eq!(
                    matches.len(),
                    1,
                    "exactly one zeroed-agent debit must surface: {drift:?}"
                );
                assert_eq!(
                    matches[0].id.as_deref(),
                    Some(receipt_id.to_string().as_str())
                );
                assert!(
                    matches[0].message.contains("agent.pubkey = [0u8; 32]")
                        && matches[0].message.contains("ed25519"),
                    "message should name the zeroed pubkey and the ed25519 invariant: {}",
                    matches[0].message
                );
                assert!(
                    matches[0]
                        .repair
                        .contains("sixth carrier of the zeroed-pubkey family")
                        && matches[0].repair.contains("receipt_payer_pubkey_zeroed"),
                    "repair hint should place it in the zeroed-pubkey family: {}",
                    matches[0].repair
                );
                // The shape arm owns the sentinel: the payer-mismatch join arm
                // gates on a non-zero agent, so it stays silent here.
                assert!(
                    !drift
                        .iter()
                        .any(|i| i.kind == "budget_debit_paired_receipt_payer_mismatch"),
                    "payer-mismatch must be gated out for a zeroed agent: {drift:?}"
                );
                let check = checks
                    .iter()
                    .find(|c| c.name == "budget ↔ receipts")
                    .unwrap_or_else(|| panic!("expected budget join check: {checks:?}"));
                assert!(!check.passed);
                assert!(
                    check.message.contains("1 zeroed-agent-pubkey debit")
                        && check.message.contains("0 payer-mismatched debit"),
                    "check message should count the zeroed-agent debit and show payer-mismatch silent: {}",
                    check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

