    #[tokio::test]
    async fn verify_reports_audit_operator_token_rotated_issuer_not_trust_root_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        // OperatorTokenRotated is peer-issued via record_peer_event, but its sole
        // writer rotate_operator_token reaches the success site only past the
        // operator-identity gate (lib.rs:3001, no capability fallback), so the
        // acting peer is pinned to the operator whose pubkey == the trust root.
        // peer_display mirrors issuer.display and the token prefixes are valid
        // 6-char base58 so only the issuer arm fires.
        let attacker = LocalIdentity::generate("attacker@local");
        let attacker_id = attacker.agent_id();
        let tampered_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: tampered_id,
                timestamp_ms: epoch_ms(),
                issuer: attacker_id.clone(),
                kind: AuditKind::OperatorTokenRotated {
                    peer_display: attacker_id.display.clone(),
                    old_token_prefix: "abcdef".into(),
                    new_token_prefix: "123456".into(),
                },
            })
            .await
            .unwrap();
        // A faithfully-recorded row (issuer = daemon trust root) must NOT fire.
        let clean_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: clean_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::OperatorTokenRotated {
                    peer_display: me.display.clone(),
                    old_token_prefix: "abcdef".into(),
                    new_token_prefix: "123456".into(),
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "audit_operator_token_rotated_issuer_not_trust_root"
                            && item.id.as_deref() == Some(&tampered_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "expected audit_operator_token_rotated_issuer_not_trust_root: {drift:?}"
                        )
                    });
                assert!(
                    row.message.contains("trust root"),
                    "drift message should name the trust-root binding: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("rotate_operator_token"),
                    "repair hint should name the sole writer: {}",
                    row.repair
                );
                assert!(
                    !drift.iter().any(|item| {
                        item.kind == "audit_event_issuer_pubkey_zeroed"
                            && item.id.as_deref() == Some(&tampered_id.to_string())
                    }),
                    "a non-zero tampered issuer must not trip the zeroed-pubkey arm: {drift:?}"
                );
                assert!(
                    !drift.iter().any(|item| {
                        item.kind == "audit_operator_token_rotated_peer_display_not_issuer_display"
                            && item.id.as_deref() == Some(&tampered_id.to_string())
                    }),
                    "peer_display mirrors issuer.display so the display arm must stay silent: {drift:?}"
                );
                assert!(
                    !drift.iter().any(|item| {
                        item.kind == "audit_operator_token_rotated_issuer_not_trust_root"
                            && item.id.as_deref() == Some(&clean_id.to_string())
                    }),
                    "a daemon-issued OperatorTokenRotated row must not fire: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 not-trust-root-issuer OperatorTokenRotated audit event"),
                    "check message should count not-trust-root-issuer OperatorTokenRotated events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

