    async fn verify_reports_audit_memory_compaction_applied_issuer_not_trust_root_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        // MemoryCompactionApplied is peer-issued via record_peer_event, but its
        // sole writer compact_memory reaches the success site only past the
        // operator-identity gate (no capability fallback), so the acting peer is
        // pinned to the operator whose pubkey == the trust root. The payload is a
        // clean dry-run (mode "dry_run", changed false, empty vecs, non-empty
        // reason) so no field-value arm fires and only the issuer arm does.
        let attacker = LocalIdentity::generate("attacker@local");
        let attacker_id = attacker.agent_id();
        let tampered_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: tampered_id,
                timestamp_ms: epoch_ms(),
                issuer: attacker_id.clone(),
                kind: AuditKind::MemoryCompactionApplied {
                    mode: "dry_run".into(),
                    changed: false,
                    reason: "scheduled compaction".into(),
                    deleted: vec![],
                    stale_marked: vec![],
                    parents_detached: vec![],
                },
            })
            .await
            .unwrap();
        let clean_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: clean_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryCompactionApplied {
                    mode: "dry_run".into(),
                    changed: false,
                    reason: "scheduled compaction".into(),
                    deleted: vec![],
                    stale_marked: vec![],
                    parents_detached: vec![],
                },
            })
            .await
            .unwrap();

        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "audit_memory_compaction_applied_issuer_not_trust_root"
                            && item.id.as_deref() == Some(&tampered_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "expected audit_memory_compaction_applied_issuer_not_trust_root: {drift:?}"
                        )
                    });
                assert!(
                    row.message.contains("trust root"),
                    "drift message should name the trust-root binding: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("compact_memory"),
                    "repair hint should name the sole writer: {}",
                    row.repair
                );
                assert!(
                    !drift.iter().any(|item| {
                        item.kind == "audit_event_issuer_pubkey_zeroed"
                            && item.id.as_deref() == Some(&tampered_id.to_string())
                    }),
                    "a non-zero tampered issuer must not trip the zeroed-pubkey arm: {drift:?}"
                );
                assert!(
                    !drift.iter().any(|item| {
                        item.kind == "audit_memory_compaction_applied_issuer_not_trust_root"
                            && item.id.as_deref() == Some(&clean_id.to_string())
                    }),
                    "a trust-root-issued MemoryCompactionApplied row must not fire: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 not-trust-root-issuer MemoryCompactionApplied audit event"),
                    "check message should count not-trust-root-issuer MemoryCompactionApplied events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

