    #[tokio::test]
    async fn verify_reports_memory_repair_applied_deleted_record_still_present_drift() {
        use covenant_audit::{AuditEvent, AuditKind};

        // Positive: an action = "delete_record" repair row with changed = true
        // claims to have deleted a record that is still present in the store.
        // changed = true means covenant-memory ran self.delete(id) before this
        // audit row existed, and memory ids are never re-minted.
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let surviving = Uuid::new_v4();
        s.memory
            .put(MemoryRecord {
                id: surviving,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: "should have been deleted".into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: epoch_ms(),
                parent: None,
            })
            .await
            .unwrap();
        let event_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryRepairApplied {
                    memory_id: surviving,
                    action: "delete_record".into(),
                    mode: "apply".into(),
                    changed: true,
                    reason: "test".into(),
                },
            })
            .await
            .unwrap();
        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "memory_repair_applied_deleted_record_still_present"
                            && item.id.as_deref() == Some(&event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!("expected memory_repair_applied_deleted_record_still_present: {drift:?}")
                    });
                assert!(
                    row.message.contains("AuditKind::MemoryRepairApplied")
                        && row.message.contains(&surviving.to_string())
                        && row.message.contains("delete_record"),
                    "drift message should name the variant, the surviving id, and the delete action: {}",
                    row.message
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 deleted-record-still-present MemoryRepairApplied audit event"),
                    "check message should count deleted-record-still-present events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }

        // Negative: a non-delete repair action (detach_parent) keeps the record
        // present by design, so its memory_id must not trip the arm.
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let kept = Uuid::new_v4();
        s.memory
            .put(MemoryRecord {
                id: kept,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: "parent detached, record kept".into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: epoch_ms(),
                parent: None,
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: Uuid::new_v4(),
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryRepairApplied {
                    memory_id: kept,
                    action: "detach_parent".into(),
                    mode: "apply".into(),
                    changed: true,
                    reason: "detach".into(),
                },
            })
            .await
            .unwrap();
        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport { drift, .. } => assert!(
                !drift
                    .iter()
                    .any(|item| item.kind == "memory_repair_applied_deleted_record_still_present"),
                "a detach_parent repair must not trip the deleted-record-still-present arm: {drift:?}"
            ),
            other => panic!("unexpected: {other:?}"),
        }

        // Negative: a faithful delete_record whose memory_id is absent from the
        // store (the expected post-deletion state) stays silent.
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        s.audit
            .record(AuditEvent {
                id: Uuid::new_v4(),
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryRepairApplied {
                    memory_id: Uuid::new_v4(),
                    action: "delete_record".into(),
                    mode: "apply".into(),
                    changed: true,
                    reason: "deleted".into(),
                },
            })
            .await
            .unwrap();
        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport { drift, .. } => assert!(
                !drift
                    .iter()
                    .any(|item| item.kind == "memory_repair_applied_deleted_record_still_present"),
                "a delete_record repair whose memory_id is absent must stay silent: {drift:?}"
            ),
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_memory_repair_applied_backfilled_record_missing_provenance_drift() {
        use covenant_audit::{AuditEvent, AuditKind};

        // Positive: an action = "backfill_provenance" repair row with changed = true
        // whose record is present but whose object metadata lacks a "provenance"
        // key. changed = true means covenant-memory put the record with provenance
        // inserted before this audit row existed, so a present record without the
        // key is a backfill the audit claims yet the store contradicts.
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let stripped = Uuid::new_v4();
        s.memory
            .put(MemoryRecord {
                id: stripped,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: "should carry provenance".into(),
                embedding: vec![],
                metadata: serde_json::json!({ "intent_text": "x" }),
                created_at: epoch_ms(),
                parent: None,
            })
            .await
            .unwrap();
        let event_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryRepairApplied {
                    memory_id: stripped,
                    action: "backfill_provenance".into(),
                    mode: "apply".into(),
                    changed: true,
                    reason: "test".into(),
                },
            })
            .await
            .unwrap();
        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "memory_repair_applied_backfilled_record_missing_provenance"
                            && item.id.as_deref() == Some(&event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!("expected memory_repair_applied_backfilled_record_missing_provenance: {drift:?}")
                    });
                assert!(
                    row.message.contains("AuditKind::MemoryRepairApplied")
                        && row.message.contains(&stripped.to_string())
                        && row.message.contains("provenance"),
                    "drift message should name the variant, the record id, and the missing key: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("provenance-backfill complement")
                        && row.repair.contains("dry_run"),
                    "repair hint should frame the complement and the dry_run exemption: {}",
                    row.repair
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity.message.contains(
                        "1 backfilled-record-missing-provenance MemoryRepairApplied audit event"
                    ),
                    "check message should count backfilled-record-missing-provenance events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }

        // Negative (faithful): the record carries the provenance key backfill
        // inserts, the expected post-backfill state.
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let ok = Uuid::new_v4();
        s.memory
            .put(MemoryRecord {
                id: ok,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: "faithfully backfilled".into(),
                embedding: vec![],
                metadata: serde_json::json!({ "provenance": { "source": "import" } }),
                created_at: epoch_ms(),
                parent: None,
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: Uuid::new_v4(),
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryRepairApplied {
                    memory_id: ok,
                    action: "backfill_provenance".into(),
                    mode: "apply".into(),
                    changed: true,
                    reason: "applied".into(),
                },
            })
            .await
            .unwrap();
        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport { drift, .. } => assert!(
                !drift.iter().any(|item| item.kind
                    == "memory_repair_applied_backfilled_record_missing_provenance"),
                "a record carrying provenance must not trip the arm: {drift:?}"
            ),
            other => panic!("unexpected: {other:?}"),
        }

        // Negative (dry_run): a preview with changed = false mutates nothing, so a
        // record without provenance is legitimate and must not trip the arm.
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let candidate = Uuid::new_v4();
        s.memory
            .put(MemoryRecord {
                id: candidate,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: "preview".into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: epoch_ms(),
                parent: None,
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: Uuid::new_v4(),
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryRepairApplied {
                    memory_id: candidate,
                    action: "backfill_provenance".into(),
                    mode: "dry_run".into(),
                    changed: false,
                    reason: "preview".into(),
                },
            })
            .await
            .unwrap();
        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport { drift, .. } => assert!(
                !drift.iter().any(|item| item.kind
                    == "memory_repair_applied_backfilled_record_missing_provenance"),
                "dry-run preview must not trip the arm: {drift:?}"
            ),
            other => panic!("unexpected: {other:?}"),
        }

        // Negative (absent): a changed = true backfill whose record was later
        // deleted (absent from the store) is not this arm's concern.
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        s.audit
            .record(AuditEvent {
                id: Uuid::new_v4(),
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryRepairApplied {
                    memory_id: Uuid::new_v4(),
                    action: "backfill_provenance".into(),
                    mode: "apply".into(),
                    changed: true,
                    reason: "applied".into(),
                },
            })
            .await
            .unwrap();
        match s.op_respond(Request::Verify { window: 100 }).await {
            Response::VerifyReport { drift, .. } => assert!(
                !drift.iter().any(|item| item.kind
                    == "memory_repair_applied_backfilled_record_missing_provenance"),
                "an absent record must stay silent: {drift:?}"
            ),
            other => panic!("unexpected: {other:?}"),
        }
    }

