    #[tokio::test]
    async fn verify_reports_audit_memory_compaction_applied_apply_changed_false_vecs_nonempty_drift(
    ) {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let event_id = Uuid::new_v4();
        // Apply mode with a populated deleted slice forces would_change = true,
        // which forces changed = true at covenant-memory/src/lib.rs:384, so a
        // changed = false row is structurally impossible at the write-site. A
        // dry_run row may legitimately carry this shape (preview), which is why
        // the arm is gated on mode == "apply".
        let deleted_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryCompactionApplied {
                    mode: "apply".into(),
                    reason: "compaction drift".into(),
                    deleted: vec![deleted_id],
                    stale_marked: Vec::new(),
                    parents_detached: Vec::new(),
                    changed: false,
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind
                            == "audit_memory_compaction_applied_apply_changed_false_vecs_nonempty"
                            && item.id.as_deref() == Some(&event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "expected audit_memory_compaction_applied_apply_changed_false_vecs_nonempty: {drift:?}"
                        )
                    });
                assert!(
                    row.message.contains("AuditKind::MemoryCompactionApplied")
                        && row.message.contains("mode = \"apply\"")
                        && row.message.contains("changed = false"),
                    "drift message should name the variant, apply mode, and changed=false: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("plan_compaction") && row.repair.contains("would_change"),
                    "repair hint should name plan_compaction and would_change: {}",
                    row.repair
                );
                // The apply-direction arm must not double-count as either
                // changed=true sibling (both require changed = true).
                assert!(
                    drift.iter().all(|item| {
                        item.kind != "audit_memory_compaction_applied_changed_true_vecs_all_empty"
                            && item.kind != "audit_memory_compaction_applied_dry_run_changed_true"
                    }),
                    "apply-changed-false arm must not trip the changed=true siblings: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity.message.contains(
                        "1 apply-changed-false-vecs-nonempty MemoryCompactionApplied audit event"
                    ),
                    "check message should count apply-changed-false-vecs-nonempty MemoryCompactionApplied events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_audit_memory_compaction_applied_deleted_overlaps_kept_outcome_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();

        // Drift row: id_a is in both deleted and stale_marked; id_b is in both
        // deleted and parents_detached. plan_compaction's continue-before-push
        // skip makes either overlap impossible at the write-site.
        let id_a = Uuid::new_v4();
        let id_b = Uuid::new_v4();
        let mut deleted = vec![id_a, id_b];
        deleted.sort();
        let drift_event_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: drift_event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryCompactionApplied {
                    mode: "apply".into(),
                    reason: "compaction drift".into(),
                    deleted,
                    stale_marked: vec![id_a],
                    parents_detached: vec![id_b],
                    changed: true,
                },
            })
            .await
            .unwrap();

        // Legitimate row: id_c is in both stale_marked and parents_detached but
        // not deleted — a long-term record with a stale parent is detached and
        // marked in the same plan_compaction iteration, so this overlap is
        // reachable and must NOT be flagged.
        let id_c = Uuid::new_v4();
        let clean_event_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: clean_event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryCompactionApplied {
                    mode: "apply".into(),
                    reason: "stale parent and stale record".into(),
                    deleted: Vec::new(),
                    stale_marked: vec![id_c],
                    parents_detached: vec![id_c],
                    changed: true,
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "audit_memory_compaction_applied_deleted_overlaps_kept_outcome"
                            && item.id.as_deref() == Some(&drift_event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "expected audit_memory_compaction_applied_deleted_overlaps_kept_outcome: {drift:?}"
                        )
                    });
                assert!(
                    row.message.contains("AuditKind::MemoryCompactionApplied")
                        && row
                            .message
                            .contains("deleted and stale_marked or parents_detached"),
                    "drift message should name the deleted-vs-kept-outcome overlap: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("plan_compaction") && row.repair.contains("continue"),
                    "repair hint should name plan_compaction and the continue-before-push skip: {}",
                    row.repair
                );
                assert!(
                    !drift.iter().any(|item| {
                        item.kind
                            == "audit_memory_compaction_applied_deleted_overlaps_kept_outcome"
                            && item.id.as_deref() == Some(&clean_event_id.to_string())
                    }),
                    "a legitimate stale_marked/parents_detached overlap with no deleted member must not be flagged: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity.message.contains(
                        "1 deleted-overlaps-kept-outcome MemoryCompactionApplied audit event"
                    ),
                    "check message should count deleted-overlaps-kept-outcome MemoryCompactionApplied events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_audit_memory_compaction_applied_vec_contains_duplicate_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();

        // A repeated id within stale_marked. plan_compaction builds each vec
        // from unique sources, so a duplicate cannot occur in production. The
        // existing unsorted arm uses windows(2).any(|w| w[0] > w[1]) (strict
        // >), which treats [dup, dup] as ordered, so only this arm fires.
        let dup = Uuid::new_v4();
        let event_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::MemoryCompactionApplied {
                    mode: "apply".into(),
                    reason: "compaction drift".into(),
                    deleted: Vec::new(),
                    stale_marked: vec![dup, dup],
                    parents_detached: Vec::new(),
                    changed: true,
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "audit_memory_compaction_applied_vec_contains_duplicate"
                            && item.id.as_deref() == Some(&event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "expected audit_memory_compaction_applied_vec_contains_duplicate: {drift:?}"
                        )
                    });
                assert!(
                    row.message.contains("AuditKind::MemoryCompactionApplied")
                        && row.message.contains("repeated id"),
                    "drift message should name the repeated-id invariant: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("plan_compaction") && row.repair.contains("BTreeSet"),
                    "repair hint should name plan_compaction and the BTreeSet uniqueness source: {}",
                    row.repair
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 vec-contains-duplicate MemoryCompactionApplied audit event"),
                    "check message should count vec-contains-duplicate MemoryCompactionApplied events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

