    #[tokio::test]
    async fn verify_reports_audit_peer_revoked_token_prefix_not_base58_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let event_id = Uuid::new_v4();
        // 6 chars (passes the != 6 wrong-length arm) but the leading '0' is not
        // in the Bitcoin base58 alphabet, so only the charset arm fires.
        let token_prefix = "0abcde";
        assert_eq!(
            token_prefix.chars().count(),
            6,
            "fixture prefix must sit at the 6-char length bound so the wrong_length arm stays orthogonal"
        );
        assert!(
            bs58::decode(token_prefix.as_bytes()).into_vec().is_err(),
            "fixture prefix must fail bs58::decode (contains the non-base58 char '0')"
        );
        s.audit
            .record(AuditEvent {
                id: event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::PeerRevoked {
                    peer_display: "guest@local".into(),
                    peer_pubkey_b58: bs58::encode([1u8; 32]).into_string(),
                    token_prefix: token_prefix.into(),
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "audit_peer_revoked_token_prefix_not_base58"
                            && item.id.as_deref() == Some(&event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!("expected audit_peer_revoked_token_prefix_not_base58: {drift:?}")
                    });
                assert!(
                    row.message.contains("AuditKind::PeerRevoked")
                        && row.message.contains("fails bs58::decode"),
                    "drift message should name the PeerRevoked variant and the bs58::decode invariant: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("token_b58_prefix")
                        && row.repair.contains("bs58::decode")
                        && row.repair.contains("Bitcoin base58 alphabet"),
                    "repair hint should name token_b58_prefix, bs58::decode, and the base58 alphabet: {}",
                    row.repair
                );
                assert!(
                    drift.iter().all(|item| {
                        item.kind != "audit_peer_revoked_token_prefix_empty"
                            && item.kind != "audit_peer_revoked_token_prefix_wrong_length"
                    }),
                    "charset arm must not double-count as the empty or wrong-length arm: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 not-base58-charset-token-prefix PeerRevoked audit event"),
                    "check message should count not-base58-charset-token-prefix PeerRevoked events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

