    #[tokio::test]
    async fn verify_reports_audit_peer_self_revoke_blocked_peer_pubkey_b58_not_daemon_trust_root_drift(
    ) {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();

        // Tampered: a well-formed 32-byte non-zero pubkey that is NOT the
        // daemon trust root. PeerSelfRevokeBlocked only fires when the
        // self-revoke target is the operator's own identity, so this is drift.
        let foreign = [7u8; 32];
        assert_ne!(
            foreign, me.pubkey,
            "fixture foreign pubkey must differ from the daemon identity"
        );
        let foreign_b58 = bs58::encode(foreign).into_string();
        assert!(
            (32..=44).contains(&foreign_b58.chars().count()),
            "fixture pubkey must sit inside the 32..=44 length bound so the shape arms stay silent"
        );
        let tampered_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: tampered_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::PeerSelfRevokeBlocked {
                    peer_display: "guest@local".into(),
                    peer_pubkey_b58: foreign_b58,
                    token_prefix: "abcdef".into(),
                },
            })
            .await
            .unwrap();

        // Control: a faithful row whose peer_pubkey_b58 IS the trust root.
        let control_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: control_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::PeerSelfRevokeBlocked {
                    peer_display: "guest@local".into(),
                    peer_pubkey_b58: bs58::encode(me.pubkey).into_string(),
                    token_prefix: "abcdef".into(),
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind
                            == "audit_peer_self_revoke_blocked_peer_pubkey_b58_not_daemon_trust_root"
                            && item.id.as_deref() == Some(&tampered_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!("expected audit_peer_self_revoke_blocked_peer_pubkey_b58_not_daemon_trust_root: {drift:?}")
                    });
                assert!(
                    row.message.contains("AuditKind::PeerSelfRevokeBlocked")
                        && row.message.contains("daemon trust root"),
                    "drift message should name the PeerSelfRevokeBlocked variant and the trust-root invariant: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("payload-pubkey-equals-trust-root")
                        && row.repair.contains("issuer_not_trust_root"),
                    "repair hint should frame the payload-equals-trust-root invariant against the issuer family: {}",
                    row.repair
                );
                assert!(
                    drift
                        .iter()
                        .all(|item| { item.id.as_deref() != Some(&control_id.to_string()) }),
                    "the trust-root control row must produce no drift: {drift:?}"
                );
                assert!(
                    drift.iter().all(|item| {
                        item.kind != "audit_peer_self_revoke_blocked_peer_pubkey_b58_empty"
                            && item.kind
                                != "audit_peer_self_revoke_blocked_peer_pubkey_b58_wrong_length"
                            && item.kind
                                != "audit_peer_self_revoke_blocked_peer_pubkey_b58_not_base58"
                            && item.kind
                                != "audit_peer_self_revoke_blocked_peer_pubkey_b58_decodes_to_wrong_byte_length"
                            && item.kind
                                != "audit_peer_self_revoke_blocked_peer_pubkey_b58_decodes_to_all_zero_bytes"
                    }),
                    "trust-root arm must not double-count as any of the five shape arms: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity.message.contains(
                        "1 not-daemon-trust-root-peer-pubkey-b58 PeerSelfRevokeBlocked audit event"
                    ),
                    "check message should count not-daemon-trust-root-peer-pubkey-b58 PeerSelfRevokeBlocked events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

