    #[tokio::test]
    async fn verify_reports_audit_authentication_failed_issuer_not_trust_root_drift() {
        use covenant_audit::{AuditEvent, AuditKind};
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        // AuthenticationFailed is exclusively daemon-authored: record_auth_failure
        // stamps issuer = self.identity.agent_id(). An out-of-band edit rewrites the
        // issuer to a foreign non-zero key, detaching the failed-auth probe from the
        // operator's issuer-filtered /audit feed. The issuer is well-formed and
        // non-zero, so audit_event_issuer_pubkey_zeroed cannot catch it.
        let attacker = LocalIdentity::generate("attacker@local");
        let tampered_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: tampered_id,
                timestamp_ms: epoch_ms(),
                issuer: attacker.agent_id(),
                kind: AuditKind::AuthenticationFailed {
                    transport: "ipc".into(),
                    reason: "unknown or revoked token".into(),
                },
            })
            .await
            .unwrap();
        // A faithfully-recorded row (issuer = daemon trust root) must NOT fire.
        let clean_id = Uuid::new_v4();
        s.audit
            .record(AuditEvent {
                id: clean_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::AuthenticationFailed {
                    transport: "http".into(),
                    reason: "missing Authorization header".into(),
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "audit_authentication_failed_issuer_not_trust_root"
                            && item.id.as_deref() == Some(&tampered_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!(
                            "expected audit_authentication_failed_issuer_not_trust_root: {drift:?}"
                        )
                    });
                assert!(
                    row.message.contains("trust root"),
                    "drift message should name the trust-root binding: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("record_auth_failure"),
                    "repair hint should name the sole writer: {}",
                    row.repair
                );
                // Strictly disjoint from the all-zero shape arm: the tampered
                // issuer is a well-formed non-zero key.
                assert!(
                    !drift.iter().any(|item| {
                        item.kind == "audit_event_issuer_pubkey_zeroed"
                            && item.id.as_deref() == Some(&tampered_id.to_string())
                    }),
                    "a non-zero tampered issuer must not trip the zeroed-pubkey arm: {drift:?}"
                );
                // No false positive on the faithfully daemon-issued row.
                assert!(
                    !drift.iter().any(|item| {
                        item.kind == "audit_authentication_failed_issuer_not_trust_root"
                            && item.id.as_deref() == Some(&clean_id.to_string())
                    }),
                    "a daemon-issued AuthenticationFailed row must not fire: {drift:?}"
                );
                let integrity = checks
                    .iter()
                    .find(|c| c.name == "audit event integrity")
                    .unwrap_or_else(|| panic!("expected audit event integrity check: {checks:?}"));
                assert!(!integrity.passed);
                assert!(
                    integrity
                        .message
                        .contains("1 not-trust-root-issuer AuthenticationFailed audit event"),
                    "check message should count not-trust-root-issuer AuthenticationFailed events: {}",
                    integrity.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

