    #[tokio::test]
    async fn verify_reports_memory_record_receipt_id_backref_payer_not_matching_owner_drift() {
        // metadata.receipt_id is written only by covenant-memory's
        // receipt-correlation backfill, which correlates a legacy Memory receipt
        // with a memory record only when memory.owner.pubkey ==
        // receipt.payer.pubkey, so a back-reference resolving to a foreign-payer
        // receipt is a pairing no production backfill emits. Build
        // legacy-correlated records (no forward memory_record_id) plus a balancing
        // legacy receipt per owner so the count arms stay clean and only the new
        // back-reference arm can flip the check.
        async fn put_dispatch_memory(
            s: &Server,
            id: Uuid,
            owner: &AgentId,
            text: &str,
            metadata: serde_json::Value,
        ) {
            s.memory
                .put(MemoryRecord {
                    id,
                    tier: MemoryTier::Working,
                    owner: owner.clone(),
                    text: text.to_string(),
                    embedding: vec![],
                    metadata,
                    created_at: 1_000,
                    parent: None,
                })
                .await
                .unwrap();
            // Pair every memory record with a faithful dispatch audit so Check 1
            // does not flag it as a memory_without_audit orphan; the metadata
            // omits the intent_text/agent_id/status sub-keys, so Check 1's
            // cross-record arms gate off and stay silent.
            s.audit
                .record(AuditEvent {
                    id: Uuid::new_v4(),
                    timestamp_ms: epoch_ms(),
                    issuer: owner.clone(),
                    kind: AuditKind::IntentDispatched {
                        intent_id: id,
                        intent_text: text.to_string(),
                        matched_agent: None,
                        result_hash_hex: hash_hex(text.as_bytes()),
                        status: "ok".into(),
                    },
                })
                .await
                .unwrap();
        }
        async fn put_legacy_memory_receipt(s: &Server, id: Uuid, payer: &AgentId, text: &str) {
            s.settlement
                .record(SettlementReceipt {
                    id,
                    payer: payer.clone(),
                    resource: ResourceKind::Memory,
                    memory_record_id: None,
                    credits_consumed: memory_write_credits(text.len()),
                    settled_at: 2_000,
                    chain: None,
                    cluster: None,
                    batch_id: None,
                    merkle_root: None,
                    tx_sig: None,
                    slot: None,
                    confirmed_at: None,
                    onchain_sig: None,
                })
                .await
                .unwrap();
        }

        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        let mut alice_pk = me.pubkey;
        alice_pk[0] ^= 0xff;
        let alice = AgentId::new("alice@local", alice_pk);

        // Tamper: a me-owned record whose metadata.receipt_id was repointed at
        // alice's Memory receipt. me's own legacy receipt balances me's count;
        // alice's record + receipt balance alice's count, so the only non-passing
        // signal is the back-reference payer mismatch.
        let tamper_id = Uuid::new_v4();
        let alice_receipt_id = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            tamper_id,
            &me,
            "backref tamper fixture",
            serde_json::json!({ "receipt_id": alice_receipt_id.to_string() }),
        )
        .await;
        put_legacy_memory_receipt(&s, Uuid::new_v4(), &me, "backref tamper fixture").await;
        put_dispatch_memory(
            &s,
            Uuid::new_v4(),
            &alice,
            "alice fixture",
            serde_json::json!({}),
        )
        .await;
        put_legacy_memory_receipt(&s, alice_receipt_id, &alice, "alice fixture").await;

        // Control: a me-owned record whose back-reference resolves to a me-owned
        // receipt — the production-valid same-pubkey pairing.
        let control_id = Uuid::new_v4();
        let control_receipt_id = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            control_id,
            &me,
            "backref control fixture",
            serde_json::json!({ "receipt_id": control_receipt_id.to_string() }),
        )
        .await;
        put_legacy_memory_receipt(&s, control_receipt_id, &me, "backref control fixture").await;

        // Gates (each balanced by a me-owned legacy receipt so only the shape of
        // metadata.receipt_id, not the count, can change the outcome): a
        // non-string value, a string that does not parse as a Uuid, and a Uuid
        // that matches no receipt in the store must all stay silent.
        let non_string_id = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            non_string_id,
            &me,
            "non-string gate",
            serde_json::json!({ "receipt_id": 123 }),
        )
        .await;
        put_legacy_memory_receipt(&s, Uuid::new_v4(), &me, "non-string gate").await;
        let unparseable_id = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            unparseable_id,
            &me,
            "unparseable gate",
            serde_json::json!({ "receipt_id": "not-a-uuid" }),
        )
        .await;
        put_legacy_memory_receipt(&s, Uuid::new_v4(), &me, "unparseable gate").await;
        let unmatched_id = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            unmatched_id,
            &me,
            "unmatched gate",
            serde_json::json!({ "receipt_id": Uuid::new_v4().to_string() }),
        )
        .await;
        put_legacy_memory_receipt(&s, Uuid::new_v4(), &me, "unmatched gate").await;

        let resp = s.op_respond(Request::Verify { window: 1000 }).await;
        let kind = "memory_record_receipt_id_backref_payer_not_matching_owner";
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let fired = |memory_id: &Uuid| {
                    drift
                        .iter()
                        .any(|i| i.kind == kind && i.id.as_deref() == Some(&memory_id.to_string()))
                };
                let row = drift
                    .iter()
                    .find(|i| i.kind == kind && i.id.as_deref() == Some(&tamper_id.to_string()))
                    .unwrap_or_else(|| panic!("expected {kind} on tamper row: {drift:?}"));
                assert!(
                    row.message.contains(&alice.pubkey_base58())
                        && row.message.contains(&me.pubkey_base58()),
                    "message should record both the receipt payer pubkey and the memory owner pubkey: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("backward-reference analog")
                        && row.repair.contains("memory_receipt_owner_mismatch"),
                    "repair hint should name the forward arm it mirrors: {}",
                    row.repair
                );
                // The tamper row must trip only this arm (counts are balanced and
                // every other field is faithful).
                assert!(
                    drift
                        .iter()
                        .all(|i| i.id.as_deref() != Some(&tamper_id.to_string()) || i.kind == kind),
                    "the back-reference arm must be the only drift on the tamper row: {drift:?}"
                );
                assert!(
                    !fired(&control_id),
                    "same-pubkey back-reference must stay silent"
                );
                assert!(
                    !fired(&non_string_id),
                    "a non-string receipt_id must stay silent"
                );
                assert!(
                    !fired(&unparseable_id),
                    "an unparseable receipt_id must stay silent"
                );
                assert!(
                    !fired(&unmatched_id),
                    "a receipt_id matching no receipt in the store must stay silent"
                );

                let receipt_check = checks
                    .iter()
                    .find(|c| c.name == "memory ↔ receipts")
                    .unwrap_or_else(|| panic!("expected receipts check: {checks:?}"));
                assert!(!receipt_check.passed);
                assert!(
                    receipt_check
                        .message
                        .contains("back-reference payer mismatch = 1"),
                    "check message should count exactly one back-reference mismatch: {}",
                    receipt_check.message
                );
                // The count-based halves of the check stay clean, proving the
                // back-reference arm alone flipped the check.
                assert!(
                    receipt_check.message.contains("count diff = 0")
                        && receipt_check.message.contains("exact drift = 0")
                        && receipt_check.message.contains("resource mismatch = 0"),
                    "only the back-reference arm should fail the check: {}",
                    receipt_check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_memory_record_receipt_id_backref_resource_not_memory_drift() {
        // covenant-memory's receipt-correlation backfill builds its legacy
        // candidate set from Memory-resource receipts only, so a metadata
        // .receipt_id back-reference resolving to a non-Memory receipt is a
        // pairing no production backfill emits. The tamper receipt shares the
        // record's payer pubkey, so the sibling payer-mismatch arm stays silent
        // and only the resource arm flips the check — proving the resource arm
        // catches a case the payer arm cannot see.
        async fn put_dispatch_memory(
            s: &Server,
            id: Uuid,
            owner: &AgentId,
            text: &str,
            metadata: serde_json::Value,
        ) {
            s.memory
                .put(MemoryRecord {
                    id,
                    tier: MemoryTier::Working,
                    owner: owner.clone(),
                    text: text.to_string(),
                    embedding: vec![],
                    metadata,
                    created_at: 1_000,
                    parent: None,
                })
                .await
                .unwrap();
            s.audit
                .record(AuditEvent {
                    id: Uuid::new_v4(),
                    timestamp_ms: epoch_ms(),
                    issuer: owner.clone(),
                    kind: AuditKind::IntentDispatched {
                        intent_id: id,
                        intent_text: text.to_string(),
                        matched_agent: None,
                        result_hash_hex: hash_hex(text.as_bytes()),
                        status: "ok".into(),
                    },
                })
                .await
                .unwrap();
        }
        async fn put_receipt(
            s: &Server,
            id: Uuid,
            payer: &AgentId,
            resource: ResourceKind,
            text: &str,
        ) {
            s.settlement
                .record(SettlementReceipt {
                    id,
                    payer: payer.clone(),
                    resource,
                    memory_record_id: None,
                    credits_consumed: memory_write_credits(text.len()),
                    settled_at: 2_000,
                    chain: None,
                    cluster: None,
                    batch_id: None,
                    merkle_root: None,
                    tx_sig: None,
                    slot: None,
                    confirmed_at: None,
                    onchain_sig: None,
                })
                .await
                .unwrap();
        }

        let s = server_with(vec![], "");
        let me = s.identity.agent_id();

        // Tamper: a me-owned record whose metadata.receipt_id resolves to a
        // me-paid Tool receipt. A balancing me-owned legacy Memory receipt keeps
        // the count/exact/legacy halves clean so only the resource arm can flip
        // the check, and the shared payer keeps the payer arm silent.
        let tamper_id = Uuid::new_v4();
        let tool_receipt_id = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            tamper_id,
            &me,
            "resource backref tamper",
            serde_json::json!({ "receipt_id": tool_receipt_id.to_string() }),
        )
        .await;
        put_receipt(
            &s,
            tool_receipt_id,
            &me,
            ResourceKind::Tool,
            "resource backref tamper",
        )
        .await;
        put_receipt(
            &s,
            Uuid::new_v4(),
            &me,
            ResourceKind::Memory,
            "resource backref tamper",
        )
        .await;

        // Control: a me-owned record whose back-reference resolves to a Memory
        // receipt — the production-valid resource.
        let control_id = Uuid::new_v4();
        let control_receipt_id = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            control_id,
            &me,
            "resource backref control",
            serde_json::json!({ "receipt_id": control_receipt_id.to_string() }),
        )
        .await;
        put_receipt(
            &s,
            control_receipt_id,
            &me,
            ResourceKind::Memory,
            "resource backref control",
        )
        .await;

        let resp = s.op_respond(Request::Verify { window: 1000 }).await;
        let kind = "memory_record_receipt_id_backref_resource_not_memory";
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let fired = |memory_id: &Uuid, k: &str| {
                    drift
                        .iter()
                        .any(|i| i.kind == k && i.id.as_deref() == Some(&memory_id.to_string()))
                };
                let row = drift
                    .iter()
                    .find(|i| i.kind == kind && i.id.as_deref() == Some(&tamper_id.to_string()))
                    .unwrap_or_else(|| panic!("expected {kind} on tamper row: {drift:?}"));
                assert!(
                    row.message.contains("Tool") && row.message.contains("rather than Memory"),
                    "message should name the offending resource: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("same-payer case that arm cannot see"),
                    "repair hint should explain what the payer arm misses: {}",
                    row.repair
                );
                // The shared payer keeps the payer-mismatch arm silent: this row
                // trips ONLY the resource arm, proving the two arms are disjoint
                // and the resource arm covers a strictly additional case.
                assert!(
                    !fired(
                        &tamper_id,
                        "memory_record_receipt_id_backref_payer_not_matching_owner"
                    ),
                    "a same-payer non-Memory back-reference must not trip the payer arm"
                );
                assert!(
                    drift
                        .iter()
                        .all(|i| i.id.as_deref() != Some(&tamper_id.to_string()) || i.kind == kind),
                    "the resource arm must be the only drift on the tamper row: {drift:?}"
                );
                assert!(
                    !fired(&control_id, kind),
                    "a Memory-resource back-reference must stay silent"
                );

                let receipt_check = checks
                    .iter()
                    .find(|c| c.name == "memory ↔ receipts")
                    .unwrap_or_else(|| panic!("expected receipts check: {checks:?}"));
                assert!(!receipt_check.passed);
                assert!(
                    receipt_check
                        .message
                        .contains("back-reference resource mismatch = 1")
                        && receipt_check
                            .message
                            .contains("back-reference payer mismatch = 0"),
                    "check message should isolate the resource mismatch: {}",
                    receipt_check.message
                );
                // The count-based halves and the forward resource pre-scan stay
                // clean, proving the back-reference resource arm alone flipped it.
                assert!(
                    receipt_check.message.contains("count diff = 0")
                        && receipt_check.message.contains("exact drift = 0")
                        && receipt_check.message.contains("resource mismatch = 0"),
                    "only the back-reference resource arm should fail the check: {}",
                    receipt_check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_memory_record_receipt_id_backref_shared_by_multiple_records_drift() {
        // metadata.receipt_id is written only by covenant-memory's
        // receipt-correlation backfill (merge_receipt_id), fed by
        // match_legacy_receipts_to_memory_records, which pairs each legacy
        // receipt with at most one uncorrelated memory record (a used_memory set
        // dedups the pairings), so a given receipt id lands in exactly one
        // record's metadata. Two records carrying the same metadata.receipt_id is
        // the memory-log leg of the receipt_id cardinality family — a second
        // record claiming a receipt that already correlated one memory write.
        // Build legacy-correlated records (no forward memory_record_id) plus a
        // balancing legacy receipt per record so the count arms stay clean and
        // only the new cardinality arm can flip the check.
        async fn put_dispatch_memory(
            s: &Server,
            id: Uuid,
            owner: &AgentId,
            text: &str,
            metadata: serde_json::Value,
        ) {
            s.memory
                .put(MemoryRecord {
                    id,
                    tier: MemoryTier::Working,
                    owner: owner.clone(),
                    text: text.to_string(),
                    embedding: vec![],
                    metadata,
                    created_at: 1_000,
                    parent: None,
                })
                .await
                .unwrap();
            s.audit
                .record(AuditEvent {
                    id: Uuid::new_v4(),
                    timestamp_ms: epoch_ms(),
                    issuer: owner.clone(),
                    kind: AuditKind::IntentDispatched {
                        intent_id: id,
                        intent_text: text.to_string(),
                        matched_agent: None,
                        result_hash_hex: hash_hex(text.as_bytes()),
                        status: "ok".into(),
                    },
                })
                .await
                .unwrap();
        }
        async fn put_legacy_memory_receipt(s: &Server, id: Uuid, payer: &AgentId, text: &str) {
            s.settlement
                .record(SettlementReceipt {
                    id,
                    payer: payer.clone(),
                    resource: ResourceKind::Memory,
                    memory_record_id: None,
                    credits_consumed: memory_write_credits(text.len()),
                    settled_at: 2_000,
                    chain: None,
                    cluster: None,
                    batch_id: None,
                    merkle_root: None,
                    tx_sig: None,
                    slot: None,
                    confirmed_at: None,
                    onchain_sig: None,
                })
                .await
                .unwrap();
        }

        let s = server_with(vec![], "");
        let me = s.identity.agent_id();

        // Tamper: two me-owned records back-referencing one receipt id. The
        // receipt itself is absent from the store, proving the cardinality arm
        // does not require the referent present (a purged or windowed-out receipt
        // must not hide a real duplicate) and keeping the per-row back-reference
        // shape arms silent (they continue when the receipt is not in the store).
        let shared = Uuid::new_v4();
        let dup_a = Uuid::new_v4();
        let dup_b = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            dup_a,
            &me,
            "shared backref a",
            serde_json::json!({ "receipt_id": shared.to_string() }),
        )
        .await;
        put_dispatch_memory(
            &s,
            dup_b,
            &me,
            "shared backref b",
            serde_json::json!({ "receipt_id": shared.to_string() }),
        )
        .await;

        // Control: a single record with its own unique back-reference must stay
        // silent (count == 1).
        let solo_id = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            solo_id,
            &me,
            "solo backref",
            serde_json::json!({ "receipt_id": Uuid::new_v4().to_string() }),
        )
        .await;

        // Gate: two records sharing the NIL receipt_id must NOT surface here —
        // the nil UUID is skipped so a defaulted or forged all-zeros
        // back-reference is not conflated with a real receipt_id collision.
        let nil_a = Uuid::new_v4();
        let nil_b = Uuid::new_v4();
        put_dispatch_memory(
            &s,
            nil_a,
            &me,
            "nil backref a",
            serde_json::json!({ "receipt_id": Uuid::nil().to_string() }),
        )
        .await;
        put_dispatch_memory(
            &s,
            nil_b,
            &me,
            "nil backref b",
            serde_json::json!({ "receipt_id": Uuid::nil().to_string() }),
        )
        .await;

        // Balance the per-owner count: five me-owned records need five me-owned
        // legacy Memory receipts so pair_diff and the legacy fallback stay clean
        // and only the cardinality arm can fail the check. Each receipt carries a
        // fresh non-nil id distinct from `shared`, so none is the referent of a
        // back-reference and receipt_id_duplicate / receipt_id_nil stay silent.
        for _ in 0..5 {
            put_legacy_memory_receipt(&s, Uuid::new_v4(), &me, "balance").await;
        }

        let resp = s.op_respond(Request::Verify { window: 1000 }).await;
        let kind = "memory_record_receipt_id_backref_shared_by_multiple_records";
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let dups: Vec<_> = drift.iter().filter(|i| i.kind == kind).collect();
                assert_eq!(
                    dups.len(),
                    1,
                    "exactly one cardinality row, and the nil pair must be skipped: {drift:?}"
                );
                let row = dups[0];
                assert_eq!(row.id.as_deref(), Some(shared.to_string().as_str()));
                assert!(
                    row.message
                        .contains("memory records carry metadata.receipt_id")
                        && row.message.contains("merge_receipt_id"),
                    "drift message should count the shared rows and name the sole writer: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("receipt_id_duplicate")
                        && row.repair.contains(
                            "external_payment_settled_receipt_id_shared_by_multiple_events"
                        )
                        && row
                            .repair
                            .contains("budget_debit_paired_receipt_shared_by_multiple_debits")
                        && row.repair.contains("memory_receipt_duplicate"),
                    "repair hint should name the sibling cardinality legs and the disjoint forward arm: {}",
                    row.repair
                );
                // The nil-sharing pair must not surface (nil skipped).
                assert!(
                    !drift.iter().any(|i| i.kind == kind
                        && i.id.as_deref() == Some(Uuid::nil().to_string().as_str())),
                    "a nil back-reference shared by two records must stay silent: {drift:?}"
                );
                // The per-row back-reference shape arms must stay silent: the
                // shared receipt is absent, so neither resolves.
                assert!(
                    !drift.iter().any(|i| i.kind
                        == "memory_record_receipt_id_backref_resource_not_memory"
                        || i.kind == "memory_record_receipt_id_backref_payer_not_matching_owner"),
                    "the per-row back-reference shape arms must stay silent: {drift:?}"
                );

                let receipt_check = checks
                    .iter()
                    .find(|c| c.name == "memory ↔ receipts")
                    .unwrap_or_else(|| panic!("expected receipts check: {checks:?}"));
                assert!(!receipt_check.passed);
                assert!(
                    receipt_check
                        .message
                        .contains("back-reference shared-by-multiple-records = 1"),
                    "check message should count exactly one shared back-reference: {}",
                    receipt_check.message
                );
                // The count-based halves and the sibling shape arms stay clean,
                // proving the cardinality arm alone flipped the check.
                assert!(
                    receipt_check.message.contains("count diff = 0")
                        && receipt_check.message.contains("exact drift = 0")
                        && receipt_check
                            .message
                            .contains("back-reference payer mismatch = 0")
                        && receipt_check
                            .message
                            .contains("back-reference resource mismatch = 0"),
                    "only the cardinality arm should fail the check: {}",
                    receipt_check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_receipt_without_memory_record_payer_not_matching_audit_issuer_drift() {
        async fn put_intent_audit(s: &Server, intent_id: Uuid, issuer: &AgentId) {
            s.audit
                .record(AuditEvent {
                    id: Uuid::new_v4(),
                    timestamp_ms: epoch_ms(),
                    issuer: issuer.clone(),
                    kind: AuditKind::IntentDispatched {
                        intent_id,
                        intent_text: "orphaned dispatch".into(),
                        matched_agent: None,
                        result_hash_hex: hash_hex(b"orphaned dispatch"),
                        status: "ok".into(),
                    },
                })
                .await
                .unwrap();
        }
        async fn put_memory_receipt(
            s: &Server,
            receipt_id: Uuid,
            memory_record_id: Uuid,
            payer: &AgentId,
        ) {
            s.settlement
                .record(SettlementReceipt {
                    id: receipt_id,
                    payer: payer.clone(),
                    resource: ResourceKind::Memory,
                    memory_record_id: Some(memory_record_id),
                    credits_consumed: 1,
                    settled_at: 2_000,
                    chain: None,
                    cluster: None,
                    batch_id: None,
                    merkle_root: None,
                    tx_sig: None,
                    slot: None,
                    confirmed_at: None,
                    onchain_sig: None,
                })
                .await
                .unwrap();
        }

        let s = server_with(vec![], "");
        let payer = AgentId::new("payer@local", [1u8; 32]);
        let issuer = AgentId::new("issuer@local", [2u8; 32]);
        let third = AgentId::new("third@local", [3u8; 32]);

        // Tamper: an orphaned Memory receipt (its memory record is absent from the
        // store) whose payer disagrees with the surviving IntentDispatched audit
        // issuer — the only thing that can detect this once the memory record both
        // rows reference has been purged.
        let tamper_intent = Uuid::new_v4();
        let tamper_receipt = Uuid::new_v4();
        put_intent_audit(&s, tamper_intent, &issuer).await;
        put_memory_receipt(&s, tamper_receipt, tamper_intent, &payer).await;

        // Control 1 (orphaned, faithful): the same identity on both feeds, the
        // production invariant — only receipt_without_memory_record fires for it.
        let faithful_intent = Uuid::new_v4();
        let faithful_receipt = Uuid::new_v4();
        put_intent_audit(&s, faithful_intent, &payer).await;
        put_memory_receipt(&s, faithful_receipt, faithful_intent, &payer).await;

        // Control 2 (memory present, divergent): receipt.payer (third) != audit
        // issuer (issuer), so the arm WOULD fire if evaluated — but the memory
        // record exists, so the None arm is never taken and the memory-anchored
        // Check 4 memory_receipt_owner_mismatch owns the divergence instead.
        let present_intent = Uuid::new_v4();
        let present_receipt = Uuid::new_v4();
        s.memory
            .put(MemoryRecord {
                id: present_intent,
                tier: MemoryTier::Working,
                owner: payer.clone(),
                text: "present".into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: 1_000,
                parent: None,
            })
            .await
            .unwrap();
        put_intent_audit(&s, present_intent, &issuer).await;
        put_memory_receipt(&s, present_receipt, present_intent, &third).await;

        let resp = s.op_respond(Request::Verify { window: 1000 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let kind = "receipt_without_memory_record_payer_not_matching_audit_issuer";
                let row = drift
                    .iter()
                    .find(|item| item.kind == kind)
                    .unwrap_or_else(|| {
                        panic!("expected orphaned payer-vs-issuer drift: {drift:?}")
                    });
                assert_eq!(row.id.as_deref(), Some(tamper_receipt.to_string().as_str()));
                assert!(
                    row.message.contains(&issuer.pubkey_base58())
                        && row.message.contains(&payer.pubkey_base58()),
                    "message should name both the audit issuer and the receipt payer pubkeys: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("third edge of the dispatch triangle"),
                    "repair should frame the binding as the third edge: {}",
                    row.repair
                );

                // Only the tamper pair trips it: the faithful orphan (payer ==
                // issuer) and the memory-present divergence both stay silent.
                let firing: Vec<&str> = drift
                    .iter()
                    .filter(|item| item.kind == kind)
                    .filter_map(|item| item.id.as_deref())
                    .collect();
                assert_eq!(
                    firing,
                    vec![tamper_receipt.to_string().as_str()],
                    "only the tamper pair should fire the orphan payer arm: {drift:?}"
                );

                // Memory-present divergence is owned by the Check 4 arm, proving
                // the new arm's memory-absent gate is disjoint from it.
                assert!(
                    drift.iter().any(|item| {
                        item.kind == "memory_receipt_owner_mismatch"
                            && item.id.as_deref() == Some(present_receipt.to_string().as_str())
                    }),
                    "memory-present divergence should route to memory_receipt_owner_mismatch: {drift:?}"
                );

                let check = checks
                    .iter()
                    .find(|c| c.name == "memory ↔ receipts")
                    .unwrap_or_else(|| panic!("expected memory↔receipts check: {checks:?}"));
                assert!(!check.passed);
                assert!(
                    check
                        .message
                        .contains("orphaned-receipt payer-vs-audit-issuer mismatch = 1"),
                    "check message should count the orphan mismatch: {}",
                    check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_receipt_without_memory_record_payer_display_not_matching_audit_issuer_drift(
    ) {
        async fn put_intent_audit(s: &Server, intent_id: Uuid, issuer: &AgentId) {
            s.audit
                .record(AuditEvent {
                    id: Uuid::new_v4(),
                    timestamp_ms: epoch_ms(),
                    issuer: issuer.clone(),
                    kind: AuditKind::IntentDispatched {
                        intent_id,
                        intent_text: "orphaned dispatch".into(),
                        matched_agent: None,
                        result_hash_hex: hash_hex(b"orphaned dispatch"),
                        status: "ok".into(),
                    },
                })
                .await
                .unwrap();
        }
        async fn put_memory_receipt(
            s: &Server,
            receipt_id: Uuid,
            memory_record_id: Uuid,
            payer: &AgentId,
        ) {
            s.settlement
                .record(SettlementReceipt {
                    id: receipt_id,
                    payer: payer.clone(),
                    resource: ResourceKind::Memory,
                    memory_record_id: Some(memory_record_id),
                    credits_consumed: 1,
                    settled_at: 2_000,
                    chain: None,
                    cluster: None,
                    batch_id: None,
                    merkle_root: None,
                    tx_sig: None,
                    slot: None,
                    confirmed_at: None,
                    onchain_sig: None,
                })
                .await
                .unwrap();
        }

        let s = server_with(vec![], "");
        // Same pubkey, two well-formed displays: the relabel a settlement-feed
        // edit produces while preserving the cryptographic identity.
        let issuer = AgentId::new("issuer@local", [7u8; 32]);
        let relabeled = AgentId::new("relabeled@local", [7u8; 32]);
        let foreign = AgentId::new("foreign@local", [9u8; 32]);

        // Tamper: an orphaned Memory receipt (its memory record absent) whose
        // payer shares the audit issuer's pubkey but carries a different display.
        // The pubkey arm cannot see it (pubkeys agree); only the display arm fires.
        let tamper_intent = Uuid::new_v4();
        let tamper_receipt = Uuid::new_v4();
        put_intent_audit(&s, tamper_intent, &issuer).await;
        put_memory_receipt(&s, tamper_receipt, tamper_intent, &relabeled).await;

        // Control 1 (orphaned, faithful): same pubkey AND same display — the
        // production invariant; only receipt_without_memory_record fires for it.
        let faithful_intent = Uuid::new_v4();
        let faithful_receipt = Uuid::new_v4();
        put_intent_audit(&s, faithful_intent, &issuer).await;
        put_memory_receipt(&s, faithful_receipt, faithful_intent, &issuer).await;

        // Control 2 (orphaned, divergent pubkey): payer.pubkey != issuer.pubkey,
        // so the pubkey arm owns it and the display arm (which requires equal
        // pubkeys) must stay silent for this receipt.
        let pubkey_intent = Uuid::new_v4();
        let pubkey_receipt = Uuid::new_v4();
        put_intent_audit(&s, pubkey_intent, &issuer).await;
        put_memory_receipt(&s, pubkey_receipt, pubkey_intent, &foreign).await;

        // Control 3 (memory present, divergent display): the record exists, so the
        // None branch is never taken and the memory-anchored
        // memory_receipt_payer_display_not_matching_owner arm owns the divergence.
        let present_intent = Uuid::new_v4();
        let present_receipt = Uuid::new_v4();
        s.memory
            .put(MemoryRecord {
                id: present_intent,
                tier: MemoryTier::Working,
                owner: issuer.clone(),
                text: "present".into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: 1_000,
                parent: None,
            })
            .await
            .unwrap();
        put_intent_audit(&s, present_intent, &issuer).await;
        put_memory_receipt(&s, present_receipt, present_intent, &relabeled).await;

        let resp = s.op_respond(Request::Verify { window: 1000 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let kind = "receipt_without_memory_record_payer_display_not_matching_audit_issuer";
                let row = drift
                    .iter()
                    .find(|item| item.kind == kind)
                    .unwrap_or_else(|| {
                        panic!("expected orphaned payer-display-vs-issuer drift: {drift:?}")
                    });
                assert_eq!(row.id.as_deref(), Some(tamper_receipt.to_string().as_str()));
                assert!(
                    row.message.contains("relabeled@local") && row.message.contains("issuer@local"),
                    "message should name both the receipt payer display and the audit issuer display: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("display half of the orphaned audit"),
                    "repair should frame the binding as the display half: {}",
                    row.repair
                );

                // Only the tamper pair trips it: faithful orphan, divergent-pubkey
                // orphan, and memory-present divergence all stay silent here.
                let firing: Vec<&str> = drift
                    .iter()
                    .filter(|item| item.kind == kind)
                    .filter_map(|item| item.id.as_deref())
                    .collect();
                assert_eq!(
                    firing,
                    vec![tamper_receipt.to_string().as_str()],
                    "only the tamper pair should fire the orphan payer-display arm: {drift:?}"
                );

                // The divergent-pubkey orphan routes to the pubkey arm, proving
                // the display arm's equal-pubkey gate is disjoint from it.
                assert!(
                    drift.iter().any(|item| {
                        item.kind == "receipt_without_memory_record_payer_not_matching_audit_issuer"
                            && item.id.as_deref() == Some(pubkey_receipt.to_string().as_str())
                    }),
                    "divergent-pubkey orphan should route to the pubkey arm: {drift:?}"
                );

                // Memory-present divergence is owned by the Check 4 owner-display
                // arm, proving the new arm's memory-absent gate is disjoint.
                assert!(
                    drift.iter().any(|item| {
                        item.kind == "memory_receipt_payer_display_not_matching_owner"
                            && item.id.as_deref() == Some(present_receipt.to_string().as_str())
                    }),
                    "memory-present divergence should route to memory_receipt_payer_display_not_matching_owner: {drift:?}"
                );

                let check = checks
                    .iter()
                    .find(|c| c.name == "memory ↔ receipts")
                    .unwrap_or_else(|| panic!("expected memory↔receipts check: {checks:?}"));
                assert!(!check.passed);
                assert!(
                    check
                        .message
                        .contains("orphaned-receipt payer-display-vs-audit-issuer mismatch = 1"),
                    "check message should count the orphan display mismatch: {}",
                    check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_receipt_without_memory_record_settled_after_dispatch_audit_drift() {
        async fn put_intent_audit_at(
            s: &Server,
            intent_id: Uuid,
            issuer: &AgentId,
            timestamp_ms: u64,
        ) {
            s.audit
                .record(AuditEvent {
                    id: Uuid::new_v4(),
                    timestamp_ms,
                    issuer: issuer.clone(),
                    kind: AuditKind::IntentDispatched {
                        intent_id,
                        intent_text: "orphaned dispatch".into(),
                        matched_agent: None,
                        result_hash_hex: hash_hex(b"orphaned dispatch"),
                        status: "ok".into(),
                    },
                })
                .await
                .unwrap();
        }
        async fn put_memory_receipt_at(
            s: &Server,
            receipt_id: Uuid,
            memory_record_id: Uuid,
            payer: &AgentId,
            settled_at: u64,
        ) {
            s.settlement
                .record(SettlementReceipt {
                    id: receipt_id,
                    payer: payer.clone(),
                    resource: ResourceKind::Memory,
                    memory_record_id: Some(memory_record_id),
                    credits_consumed: 1,
                    settled_at,
                    chain: None,
                    cluster: None,
                    batch_id: None,
                    merkle_root: None,
                    tx_sig: None,
                    slot: None,
                    confirmed_at: None,
                    onchain_sig: None,
                })
                .await
                .unwrap();
        }

        let s = server_with(vec![], "");
        // One identity for both the audit issuer and the receipt payer (same
        // pubkey AND display) so the orphan payer pubkey/display arms stay silent
        // and only the temporal arm can fire.
        let issuer = AgentId::new("issuer@local", [7u8; 32]);

        // Tamper: an orphaned Memory receipt (its memory record absent) whose
        // settled_at (2_000) is later than its dispatch audit's timestamp_ms
        // (1_000) — the forward-dated settlement a JSONL edit produces. settled_at
        // is non-zero so the receipt_settled_at_zero shape arm stays out.
        let tamper_intent = Uuid::new_v4();
        let tamper_receipt = Uuid::new_v4();
        put_intent_audit_at(&s, tamper_intent, &issuer, 1_000).await;
        put_memory_receipt_at(&s, tamper_receipt, tamper_intent, &issuer, 2_000).await;

        // Control 1 (orphaned, faithful): settled_at (1_000) <= timestamp_ms
        // (2_000), the production ordering; only receipt_without_memory_record
        // fires for it.
        let faithful_intent = Uuid::new_v4();
        let faithful_receipt = Uuid::new_v4();
        put_intent_audit_at(&s, faithful_intent, &issuer, 2_000).await;
        put_memory_receipt_at(&s, faithful_receipt, faithful_intent, &issuer, 1_000).await;

        // Control 2 (orphaned, boundary equal): settled_at == timestamp_ms, so
        // settled_at <= timestamp_ms holds and the strict > gate stays silent.
        let equal_intent = Uuid::new_v4();
        let equal_receipt = Uuid::new_v4();
        put_intent_audit_at(&s, equal_intent, &issuer, 1_500).await;
        put_memory_receipt_at(&s, equal_receipt, equal_intent, &issuer, 1_500).await;

        // Control 3 (memory present, settled after audit): the record exists, so
        // the None branch is never taken and the memory-anchored
        // memory_receipt_settled_after_dispatch_audit arm owns the inversion. Its
        // text matches the dispatch audit's hashed input so no Check 1 arm fires.
        let present_intent = Uuid::new_v4();
        let present_receipt = Uuid::new_v4();
        s.memory
            .put(MemoryRecord {
                id: present_intent,
                tier: MemoryTier::Working,
                owner: issuer.clone(),
                text: "orphaned dispatch".into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: 500,
                parent: None,
            })
            .await
            .unwrap();
        put_intent_audit_at(&s, present_intent, &issuer, 1_000).await;
        put_memory_receipt_at(&s, present_receipt, present_intent, &issuer, 2_000).await;

        let resp = s.op_respond(Request::Verify { window: 1000 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let kind = "receipt_without_memory_record_settled_after_dispatch_audit";
                let row = drift
                    .iter()
                    .find(|item| item.kind == kind)
                    .unwrap_or_else(|| {
                        panic!("expected orphaned settled-after-audit drift: {drift:?}")
                    });
                assert_eq!(row.id.as_deref(), Some(tamper_receipt.to_string().as_str()));
                assert!(
                    row.message.contains("settled_at = 2000")
                        && row.message.contains("timestamp_ms = 1000"),
                    "message should name both the receipt settled_at and the audit timestamp_ms: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("temporal edge of the orphaned audit"),
                    "repair should frame the binding as the temporal edge: {}",
                    row.repair
                );

                // Only the tamper pair trips it: faithful orphan, equal-boundary
                // orphan, and the memory-present inversion all stay silent here.
                let firing: Vec<&str> = drift
                    .iter()
                    .filter(|item| item.kind == kind)
                    .filter_map(|item| item.id.as_deref())
                    .collect();
                assert_eq!(
                    firing,
                    vec![tamper_receipt.to_string().as_str()],
                    "only the tamper pair should fire the orphan temporal arm: {drift:?}"
                );

                // Memory-present inversion is owned by the Check 4 Some-branch arm,
                // proving the new arm's memory-absent gate is disjoint from it.
                assert!(
                    drift.iter().any(|item| {
                        item.kind == "memory_receipt_settled_after_dispatch_audit"
                            && item.id.as_deref() == Some(present_receipt.to_string().as_str())
                    }),
                    "memory-present inversion should route to memory_receipt_settled_after_dispatch_audit: {drift:?}"
                );

                let check = checks
                    .iter()
                    .find(|c| c.name == "memory ↔ receipts")
                    .unwrap_or_else(|| panic!("expected memory↔receipts check: {checks:?}"));
                assert!(!check.passed);
                assert!(
                    check
                        .message
                        .contains("orphaned-receipt settled-after-dispatch-audit = 1"),
                    "check message should count the orphan temporal mismatch: {}",
                    check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_intent_dispatched_result_hash_not_derived_from_memory_text_drift() {
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        // Tamper: an IntentDispatched whose result_hash_hex is a well-formed
        // 64-char lowercase-hex digest (so it clears all four shape arms) but
        // is hash_hex of a DIFFERENT string than the joined memory record's
        // text — exactly what a rewritten dispatch digest looks like.
        let tamper_intent_id = Uuid::new_v4();
        let tamper_event_id = Uuid::new_v4();
        let tamper_text = "result-hash tamper fixture";
        let tamper_stored = hash_hex(b"a different result than was stored");
        let tamper_expected = hash_hex(tamper_text.as_bytes());
        s.memory
            .put(MemoryRecord {
                id: tamper_intent_id,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: tamper_text.into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: 1_000,
                parent: None,
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: tamper_event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::IntentDispatched {
                    intent_id: tamper_intent_id,
                    intent_text: tamper_text.into(),
                    matched_agent: None,
                    result_hash_hex: tamper_stored.clone(),
                    status: "ok".into(),
                },
            })
            .await
            .unwrap();
        // Control: result_hash_hex IS hash_hex(memory.text) — must not fire,
        // proving the arm recomputes through the producer's hash_hex.
        let ok_intent_id = Uuid::new_v4();
        let ok_event_id = Uuid::new_v4();
        let ok_text = "result-hash control fixture";
        s.memory
            .put(MemoryRecord {
                id: ok_intent_id,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: ok_text.into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: 1_000,
                parent: None,
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: ok_event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::IntentDispatched {
                    intent_id: ok_intent_id,
                    intent_text: ok_text.into(),
                    matched_agent: None,
                    result_hash_hex: hash_hex(ok_text.as_bytes()),
                    status: "ok".into(),
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "intent_dispatched_result_hash_not_derived_from_memory_text"
                            && item.id.as_deref() == Some(&tamper_event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!("expected intent_dispatched_result_hash_not_derived_from_memory_text: {drift:?}")
                    });
                assert!(
                    row.message.contains(tamper_stored.as_str())
                        && row.message.contains(tamper_expected.as_str()),
                    "message should record the stored digest and the recomputed hash_hex(memory.text): {}",
                    row.message
                );
                assert!(
                    row.repair.contains("covenant_audit::hash_hex")
                        && row.repair.contains("_all_zeros"),
                    "repair hint should name the shared hash_hex and the disjoint shape arms: {}",
                    row.repair
                );
                // The canonical-but-wrong digest must not double-report under any
                // of the four result_hash_hex shape arms.
                assert!(
                    drift.iter().all(|item| {
                        item.id.as_deref() != Some(&tamper_event_id.to_string())
                            || (item.kind != "audit_intent_dispatched_result_hash_hex_empty"
                                && item.kind
                                    != "audit_intent_dispatched_result_hash_hex_wrong_length"
                                && item.kind
                                    != "audit_intent_dispatched_result_hash_hex_not_lowercase_hex"
                                && item.kind
                                    != "audit_intent_dispatched_result_hash_hex_all_zeros")
                    }),
                    "derivation arm must be disjoint from the result_hash_hex shape arms: {drift:?}"
                );
                // The canonical control pair must not trip the arm.
                assert!(
                    drift.iter().all(|item| {
                        item.kind != "intent_dispatched_result_hash_not_derived_from_memory_text"
                            || item.id.as_deref() != Some(&ok_event_id.to_string())
                    }),
                    "a row whose result_hash_hex equals hash_hex(memory.text) must not trip the arm: {drift:?}"
                );
                let audit_check = checks
                    .iter()
                    .find(|c| c.name == "memory ↔ audit")
                    .unwrap_or_else(|| panic!("expected memory ↔ audit check: {checks:?}"));
                assert!(!audit_check.passed);
                assert!(
                    audit_check.message.contains("result-hash-not-derived"),
                    "check message should count the new arm: {}",
                    audit_check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn verify_reports_intent_dispatched_issuer_not_matching_memory_owner_drift() {
        let s = server_with(vec![], "");
        let me = s.identity.agent_id();
        // Tamper: an IntentDispatched whose issuer is a well-formed, non-zero
        // identity that differs from the joined memory record's owner — exactly
        // what a rewritten dispatcher identity looks like. result_hash_hex is the
        // faithful digest of the memory text so the result-hash derivation arm
        // stays quiet and only the issuer↔owner binding fires.
        let intruder = AgentId::new("intruder@local", [9u8; 32]);
        let intruder_b58 = intruder.pubkey_base58();
        let owner_b58 = me.pubkey_base58();
        let tamper_intent_id = Uuid::new_v4();
        let tamper_event_id = Uuid::new_v4();
        let tamper_text = "issuer-owner tamper fixture";
        s.memory
            .put(MemoryRecord {
                id: tamper_intent_id,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: tamper_text.into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: 1_000,
                parent: None,
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: tamper_event_id,
                timestamp_ms: epoch_ms(),
                issuer: intruder.clone(),
                kind: AuditKind::IntentDispatched {
                    intent_id: tamper_intent_id,
                    intent_text: tamper_text.into(),
                    matched_agent: None,
                    result_hash_hex: hash_hex(tamper_text.as_bytes()),
                    status: "ok".into(),
                },
            })
            .await
            .unwrap();
        // Control: issuer == owner — must not fire, proving the arm binds the
        // event issuer to the joined memory owner and not to a constant.
        let ok_intent_id = Uuid::new_v4();
        let ok_event_id = Uuid::new_v4();
        let ok_text = "issuer-owner control fixture";
        s.memory
            .put(MemoryRecord {
                id: ok_intent_id,
                tier: MemoryTier::Working,
                owner: me.clone(),
                text: ok_text.into(),
                embedding: vec![],
                metadata: serde_json::json!({}),
                created_at: 1_000,
                parent: None,
            })
            .await
            .unwrap();
        s.audit
            .record(AuditEvent {
                id: ok_event_id,
                timestamp_ms: epoch_ms(),
                issuer: me.clone(),
                kind: AuditKind::IntentDispatched {
                    intent_id: ok_intent_id,
                    intent_text: ok_text.into(),
                    matched_agent: None,
                    result_hash_hex: hash_hex(ok_text.as_bytes()),
                    status: "ok".into(),
                },
            })
            .await
            .unwrap();

        let resp = s.op_respond(Request::Verify { window: 100 }).await;
        match resp {
            Response::VerifyReport {
                drift,
                orphans_total,
                checks,
                ..
            } => {
                let row = drift
                    .iter()
                    .find(|item| {
                        item.kind == "intent_dispatched_issuer_not_matching_memory_owner"
                            && item.id.as_deref() == Some(&tamper_event_id.to_string())
                    })
                    .unwrap_or_else(|| {
                        panic!("expected intent_dispatched_issuer_not_matching_memory_owner: {drift:?}")
                    });
                assert!(
                    row.message.contains(intruder_b58.as_str())
                        && row.message.contains(owner_b58.as_str()),
                    "message should record the audit issuer pubkey and the memory owner pubkey: {}",
                    row.message
                );
                assert!(
                    row.repair.contains("memory_receipt_owner_mismatch")
                        && row.repair.contains("audit_event_issuer_pubkey_zeroed"),
                    "repair hint should name the mirrored receipt arm and the disjoint shape arms: {}",
                    row.repair
                );
                // Both pubkeys are non-zero, so the tampered event must not
                // double-report under the issuer/owner zeroed shape arms.
                assert!(
                    drift.iter().all(|item| {
                        item.id.as_deref() != Some(&tamper_event_id.to_string())
                            || item.kind != "audit_event_issuer_pubkey_zeroed"
                    }),
                    "issuer↔owner arm must be disjoint from audit_event_issuer_pubkey_zeroed: {drift:?}"
                );
                assert!(
                    drift.iter().all(|item| {
                        item.id.as_deref() != Some(&tamper_intent_id.to_string())
                            || item.kind != "memory_record_owner_pubkey_zeroed"
                    }),
                    "issuer↔owner arm must be disjoint from memory_record_owner_pubkey_zeroed: {drift:?}"
                );
                // The faithful-digest tamper must not trip the result-hash arm.
                assert!(
                    drift.iter().all(|item| {
                        item.id.as_deref() != Some(&tamper_event_id.to_string())
                            || item.kind
                                != "intent_dispatched_result_hash_not_derived_from_memory_text"
                    }),
                    "issuer↔owner tamper carries a faithful result_hash_hex and must not trip the result-hash arm: {drift:?}"
                );
                // The matched control pair must not trip the arm.
                assert!(
                    drift.iter().all(|item| {
                        item.kind != "intent_dispatched_issuer_not_matching_memory_owner"
                            || item.id.as_deref() != Some(&ok_event_id.to_string())
                    }),
                    "a row whose issuer.pubkey equals memory.owner.pubkey must not trip the arm: {drift:?}"
                );
                let audit_check = checks
                    .iter()
                    .find(|c| c.name == "memory ↔ audit")
                    .unwrap_or_else(|| panic!("expected memory ↔ audit check: {checks:?}"));
                assert!(!audit_check.passed);
                assert!(
                    audit_check.message.contains("issuer-not-matching-owner"),
                    "check message should count the new arm: {}",
                    audit_check.message
                );
                assert!(orphans_total >= 1);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

