    #[tokio::test]
    async fn a2a_queue_min_lease_age_filters_only_in_flight_tasks() {
        let s = server_with(vec![], "");
        let in_flight = loopback_a2a_task_for(&s);
        let result_task = covenant_a2a::A2ATask {
            id: Uuid::new_v4(),
            ..in_flight.clone()
        };
        let queued = covenant_a2a::A2ATask {
            id: Uuid::new_v4(),
            ..in_flight.clone()
        };
        s.op_respond(Request::GrantCapability {
            action: format!("a2a.send.{}", in_flight.recipient.display),
            scope: None,
            expires_at: None,
        })
        .await;
        s.op_respond(Request::GrantCapability {
            action: format!("a2a.respond.{}", in_flight.sender.display),
            scope: None,
            expires_at: None,
        })
        .await;

        s.op_respond(Request::SendA2ATask {
            task: in_flight.clone(),
        })
        .await;
        let _ = s.op_respond(Request::TryRecvA2ATask).await;

        s.op_respond(Request::SendA2ATask {
            task: result_task.clone(),
        })
        .await;
        let _ = s.op_respond(Request::TryRecvA2ATask).await;
        let result = covenant_a2a::A2ATaskResult::ok(
            result_task.id,
            vec![covenant_mcp::Content::text("done")],
        );
        s.op_respond(Request::PostA2AResult { result }).await;

        s.op_respond(Request::SendA2ATask {
            task: queued.clone(),
        })
        .await;

        let queue = s
            .op_respond(Request::A2AQueue {
                limit: 10,
                min_lease_age_ms: Some(u64::MAX),
                deadline_within_ms: None,
                state_filter: None,
            })
            .await;
        match queue {
            Response::A2AQueue { tasks, results } => {
                assert_eq!(tasks.len(), 1);
                assert_eq!(tasks[0].state, covenant_a2a::A2ATaskQueueState::Queued);
                assert_eq!(tasks[0].task.id, queued.id);
                assert_eq!(results.len(), 1);
                assert_eq!(results[0].task_id, result_task.id);
            }
            other => panic!("unexpected: {other:?}"),
        }

        let queued_only = s
            .op_respond(Request::A2AQueue {
                limit: 10,
                min_lease_age_ms: None,
                deadline_within_ms: None,
                state_filter: Some(covenant_a2a::A2ATaskQueueState::Queued),
            })
            .await;
        match queued_only {
            Response::A2AQueue { tasks, .. } => {
                assert_eq!(tasks.len(), 1);
                assert_eq!(tasks[0].state, covenant_a2a::A2ATaskQueueState::Queued);
                assert_eq!(tasks[0].task.id, queued.id);
            }
            other => panic!("unexpected: {other:?}"),
        }

        let in_flight_only = s
            .op_respond(Request::A2AQueue {
                limit: 10,
                min_lease_age_ms: None,
                deadline_within_ms: None,
                state_filter: Some(covenant_a2a::A2ATaskQueueState::InFlight),
            })
            .await;
        match in_flight_only {
            Response::A2AQueue { tasks, .. } => {
                assert_eq!(tasks.len(), 1);
                assert_eq!(tasks[0].state, covenant_a2a::A2ATaskQueueState::InFlight);
                assert_eq!(tasks[0].task.id, in_flight.id);
            }
            other => panic!("unexpected: {other:?}"),
        }

        let narrow_limit = s
            .op_respond(Request::A2AQueue {
                limit: 1,
                min_lease_age_ms: None,
                deadline_within_ms: None,
                state_filter: Some(covenant_a2a::A2ATaskQueueState::InFlight),
            })
            .await;
        match narrow_limit {
            Response::A2AQueue { tasks, .. } => {
                assert_eq!(
                    tasks.len(),
                    1,
                    "state_filter must be applied before --limit so a queued cluster cannot push in_flight rows out of the result window",
                );
                assert_eq!(tasks[0].state, covenant_a2a::A2ATaskQueueState::InFlight);
                assert_eq!(tasks[0].task.id, in_flight.id);
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

    #[tokio::test]
    async fn a2a_queue_deadline_within_filters_before_binding_limit() {
        let s = server_with(vec![], "");
        let peer = s.identity.agent_id();
        s.op_respond(Request::GrantCapability {
            action: format!("a2a.send.{}", peer.display),
            scope: None,
            expires_at: None,
        })
        .await;

        // The two undated tasks fail the deadline filter; the third,
        // queued last, carries a long-past deadline that lands inside
        // any window. Queued order is insertion order, so the only
        // match sits at index 2 — behind a binding limit of 2. A
        // take-before-filter reorder fetches the two undated rows and
        // returns nothing.
        s.op_respond(Request::SendA2ATask {
            task: loopback_a2a_task_for(&s),
        })
        .await;
        s.op_respond(Request::SendA2ATask {
            task: loopback_a2a_task_for(&s),
        })
        .await;
        let near = covenant_a2a::A2ATask {
            deadline_ms: Some(1),
            ..loopback_a2a_task_for(&s)
        };
        s.op_respond(Request::SendA2ATask { task: near.clone() })
            .await;

        let queue = s
            .op_respond(Request::A2AQueue {
                limit: 2,
                min_lease_age_ms: None,
                deadline_within_ms: Some(0),
                state_filter: None,
            })
            .await;
        match queue {
            Response::A2AQueue { tasks, .. } => {
                assert_eq!(
                    tasks.len(),
                    1,
                    "deadline_within_ms must bind before --limit so two undated tasks cannot push the only in-window task out of the result window",
                );
                assert_eq!(tasks[0].task.id, near.id);
                assert_eq!(tasks[0].task.deadline_ms, Some(1));
            }
            other => panic!("unexpected: {other:?}"),
        }
    }

